func (l *Loader) Resolve(target, baseDir string) (string, bool) {
    // normalize
    target = strings.TrimSpace(target)

    candidates := []string{}

    if isBareModuleName(target) {
        // bare name -> name/index.abs
        rel := filepath.Join(target, "index.abs")
        candidates = append(candidates, filepath.Join(baseDir, rel))
        for _, mp := range l.modulePath {
            candidates = append(candidates, filepath.Join(mp, rel))
        }
    } else {
        // path-like target
        // append index.abs if no extension
        rel := target
        if filepath.Ext(rel) == "" {
            rel = filepath.Join(rel, "index.abs")
        }
        // try baseDir first
        candidates = append(candidates, filepath.Join(baseDir, rel))
        for _, mp := range l.modulePath {
            candidates = append(candidates, filepath.Join(mp, rel))
        }
    }

    for _, cand := range candidates {
        canon, err := canonicalize(cand)
        if err != nil {
            continue
        }
        if l.exists(canon) {
            return canon, true
        }
    }
    return "", false
}
