```go
func canonicalize(path string) (string, error) {
    abs, err := filepath.Abs(path)
    if err != nil {
        return "", err
    }
    abs = filepath.Clean(abs)
    // resolve symlinks for true canonical
    resolved, err := filepath.EvalSymlinks(abs)
    if err == nil {
        abs = resolved
    }
    return abs, nil
}
```

