func requireFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
    target := args[0].Inspect()

    // Resolve to canonical path
    resolved, ok := loader.Resolve(target, env.Dir)
    if !ok {
        return newError(tok, "cannot find module: %s", target)
    }

    // Check cache
    if module, ok := loader.CacheGet(resolved); ok {
        loader.trace(env, "module-cache-hit: %s\n", resolved)
        return module
    }

    // Cycle detection
    if loader.inLoadStack(resolved) {
        chain := loader.loadStackCopy()
        chain = append(chain, resolved)
        return newError(tok, "cyclic module import detected: %s", strings.Join(chain, " -> "))
    }

    // Mark as loading
    loader.pushLoadStack(resolved)
    defer loader.popLoadStack()

    loader.trace(env, "module-load: %s\n", resolved)

    // Load the module (use doSource-like logic)
    module := doLoad(tok, env, resolved)

    // If error, don't cache
    if _, isErr := module.(*object.Error); isErr {
        return module
    }

    loader.CacheSet(resolved, module)
    return module
}
