func parseInvocationArgs(args []string) (scriptPath, modulePath string, moduleDebug bool) {
    for i := 1; i < len(args); i++ {
        arg := args[i]
        if strings.HasPrefix(arg, "-") {
            // flag
            if strings.HasPrefix(arg, "--module-path=") {
                modulePath = strings.TrimPrefix(arg, "--module-path=")
            } else if arg == "--module-path" {
                if i+1 < len(args) {
                    modulePath = args[i+1]
                    i++
                }
            } else if arg == "--module-debug" || strings.HasPrefix(arg, "--module-debug=") {
                moduleDebug = true
            }
            // unknown flags: skip, don't prevent script detection
            continue
        }
        // first non-flag arg is the script path
        scriptPath = arg
        break
    }
    return
}
