}

// Configure sets the module path and debug flag on the default loader.
func Configure(modulePath string, debug bool) {
	Default.modulePath = parseModulePath(modulePath)
	Default.debug = debug
}

// Reset clears the module cache and all loader state.
func Reset() {
	Default.cache = make(map[string]object.Object)
	Default.loadStack = nil
	Default.hits = 0
	Default.misses = 0
}

// isBareModuleName reports whether target is a bare module name: it has no
// path separator and no file extension, e.g. "demo".
func isBareModuleName(target string) bool {
	if strings.ContainsAny(target, `\/`) {
		return false
	}
	if filepath.Ext(target) != "" {
		return false
	}
	return true
}

// canonicalize returns the canonical absolute form of path. It resolves
// symlinks when possible so that equivalent paths map to the same key.
func canonicalize(path string) (string, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	abs = filepath.Clean(abs)
	if resolved, err := filepath.EvalSymlinks(abs); err == nil {
		abs = resolved
	}
	return abs, nil
}

// trimQuotes removes a single layer of surrounding quotes (single or double)
// from s, if present.
func trimQuotes(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

// parseModulePath splits a raw ABS_MODULE_PATH value into canonical
// directories. Quoted entries are normalized and equivalent canonical
// directories are deduplicated while preserving first-seen order.
func parseModulePath(raw string) []string {
	if raw == "" {
		return nil
	}
	entries := strings.Split(raw, string(os.PathListSeparator))
	seen := make(map[string]bool)
	out := []string{}
	for _, e := range entries {
		e = trimQuotes(e)
		if e == "" {
			continue
		}
		if expanded, err := util.ExpandPath(e); err == nil {
			e = expanded
		}
		canon, err := canonicalize(e)
		if err != nil {
			continue
		}
		if !seen[canon] {
			seen[canon] = true
			out = append(out, canon)
		}
	}
	return out
}

