		}
		if l.exists(canon) {
			return canon, true
		}
	}
	return "", false
}

// exists reports whether path points to a readable file.
func (l *Loader) exists(path string) bool {
	info, err := os.Stat(path)
	if err != nil {
		return false
	}
	return !info.IsDir()
}

// CacheGet returns the cached module object for key, if present.
func (l *Loader) CacheGet(key string) (object.Object, bool) {
	v, ok := l.cache[key]
	return v, ok
}

// CacheSet stores module under its canonical key.
func (l *Loader) CacheSet(key string, value object.Object) {
	l.cache[key] = value
}

// InLoadStack reports whether key is currently being loaded (i.e. present in
// the active load stack).
func (l *Loader) InLoadStack(key string) bool {
	for _, v := range l.loadStack {
		if v == key {
			return true
		}
	}
	return false
}

// PushLoadStack pushes key onto the active load stack.
func (l *Loader) PushLoadStack(key string) {
	l.loadStack = append(l.loadStack, key)
}

// PopLoadStack pops the top of the active load stack.
func (l *Loader) PopLoadStack() {
	if len(l.loadStack) > 0 {
		l.loadStack = l.loadStack[:len(l.loadStack)-1]
	}
}

// CycleChain returns the cycle chain (load stack plus the repeating key) in
// load order, joined with " -> ".
func (l *Loader) CycleChain(current string) string {
	chain := make([]string, 0, len(l.loadStack)+1)
	chain = append(chain, l.loadStack...)
	chain = append(chain, current)
	return strings.Join(chain, " -> ")
}

// CacheInfo returns the loader cache statistics.
func (l *Loader) CacheInfo() (hits, misses, size, inflight int) {
	return l.hits, l.misses, len(l.cache), len(l.loadStack)
}

// CacheKeys returns the cached module keys as sorted canonical absolute paths.
func (l *Loader) CacheKeys() []string {
	keys := make([]string, 0, len(l.cache))
	for k := range l.cache {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// trace writes a debug trace line to the runtime stderr stream when debugging
// is enabled.
func (l *Loader) trace(env *object.Environment, format string, args ...interface{}) {
	if !l.debug {
		return
	}
	w := io.Writer(os.Stderr)
	if env != nil && env.Stdio != nil && env.Stdio.Stderr != nil {
		w = env.Stdio.Stderr
	}
	fmt.Fprintf(w, format, args...)
}

// TraceResolve emits a resolve event.
func (l *Loader) TraceResolve(env *object.Environment, target, resolved string) {
	l.trace(env, "module-resolve: %s => %s\n", target, resolved)
}

// TraceLoad emits a load event.
func (l *Loader) TraceLoad(env *object.Environment, resolved string) {
	l.trace(env, "module-load: %s\n", resolved)
}

// TraceCacheHit emits a cache-hit event.
func (l *Loader) TraceCacheHit(env *object.Environment, resolved string) {
	l.trace(env, "module-cache-hit: %s\n", resolved)
}

// recordHit records a cache hit.
func (l *Loader) recordHit() {
	l.hits++
}

// recordMiss records a cache miss.
func (l *Loader) recordMiss() {
	l.misses++
}"}

