// requireStdlib loads a standard library module (@-prefixed).
func requireStdlib(tok token.Token, env *object.Environment, target string) object.Object {
	if evaluated, ok := loader.Default.CacheGet(target); ok {
		loader.Default.TraceCacheHit(env, target)
		return evaluated
