	defer loader.Default.PopLoadStack()
	loader.Default.TraceLoad(env, target)

	e := object.NewEnvironment(object.SystemStdio, filepath.Dir(target), env.Version, env.Interactive)
	evaluated := doSource(tok, e, target)

	// If a module fails to be imported, let's not cache the result
	if _, isErr := evaluated.(*object.Error); isErr {
		return evaluated
	}

	loader.Default.CacheSet(target, evaluated)
	return evaluated
