func BeginRepl(args []string, version string) {
	d, _ := os.Getwd()
	interactive := true

	// parse the full invocation arguments (argv, program name at index 0)
	scriptPath, modulePathFlag, moduleDebugFlag := parseInvocationArgs(args)

	if scriptPath != "" {
		interactive = false
		d = filepath.Dir(scriptPath)
	}

	env := object.NewEnvironment(object.SystemStdio, d, version, interactive)

