	// environment (ABS environment values first, OS environment fallback).
	modulePath := modulePathFlag
	if modulePath == "" {
		modulePath = util.GetEnvVar(env, "ABS_MODULE_PATH", "")
	}
	debug := moduleDebugFlag || isTruthyEnv(util.GetEnvVar(env, "ABS_MODULE_DEBUG", ""))
	loader.Configure(modulePath, debug)

	// This is a terminal / actual REPL
	if interactive {
		// launch the interactive terminal
		stdio := bytes.NewBufferString("")
		env.Stdio.Stdout = stdio
		env.Stdio.Stderr = stdio
		r, w, _ := os.Pipe()
		env.Stdio.Stdin = r

		term := terminal.NewTerminal(
			env,
			w,
		)

		if _, err := term.Run(); err != nil {
			log.Fatal(err)
		}

		return
	}

	// this is a script
	// let's parse our argument as a file and run it
	code, err := os.ReadFile(scriptPath)
	if err != nil {
		fmt.Fprintln(env.Stdio.Stderr, err.Error())
		os.Exit(99)
	}

	Run(string(code), env)
}

// parseInvocationArgs scans the full invocation arguments (argv, program name
// at index 0) and returns the script path, the --module-path value and whether
// --module-debug was provided. Unknown flags before the script path do not
// prevent script-path detection.
func parseInvocationArgs(args []string) (scriptPath, modulePath string, moduleDebug bool) {
	for i := 1; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "-") {
			// first non-flag argument is the script path
			return arg, modulePath, moduleDebug
		}
		switch {
		case strings.HasPrefix(arg, "--module-path="):
			modulePath = strings.TrimPrefix(arg, "--module-path=")
		case arg == "--module-path":
			if i+1 < len(args) {
				modulePath = args[i+1]
				i++
			}
		case arg == "--module-debug" || strings.HasPrefix(arg, "--module-debug="):
			moduleDebug = true
		}
		// unknown flags are skipped so they cannot prevent script detection
	}
	return "", modulePath, moduleDebug
}

// isTruthyEnv reports whether an environment value should be treated as true.
func isTruthyEnv(value string) bool {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "1", "true", "yes", "on":
		return true
	}
	return false
