func newTestLoader(modulePath string) *Loader {
	l := &Loader{cache: make(map[string]interface{})}
	_ = modulePath
	return l
}

func TestIsBareModuleName(t *testing.T) {
	cases := []struct {
		in   string
		want bool
	}{
		{"demo", true},
		{"foo", true},
		{"demo.abs", false},
		{"./demo", false},
		{"demo/index.abs", false},
		{"dir/demo", false},
		{"", false},
	}
	for _, c := range cases {
		if got := isBareModuleName(c.in); got != c.want {
			t.Errorf("isBareModuleName(%q) = %v, want %v", c.in, got, c.want)
		}
	}
}

func TestParseModulePath(t *testing.T) {
	dir1 := t.TempDir()
	dir2 := t.TempDir()
	// quoted entry + duplicate equivalent dirs + nonexistent
	raw := `"` + dir1 + `":"` + dir1 + `":` + dir2 + `:"nonexistent dir"`
	got := parseModulePath(raw)
	if len(got) != 2 {
		t.Fatalf("expected 2 entries, got %d: %v", len(got), got)
	}
	if got[0] != canonical(dir1) {
		t.Errorf("first entry = %q, want %q", got[0], canonical(dir1))
	}
	if got[1] != canonical(dir2) {
		t.Errorf("second entry = %q, want %q", got[1], canonical(dir2))
	}
}

func TestResolveBareModule(t *testing.T) {
	base := t.TempDir()
	demo := filepath.Join(base, "demo")
	if err := os.MkdirAll(filepath.Join(demo), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(demo, "index.abs"), []byte("return 1"), 0644); err != nil {
		t.Fatal(err)
	}

	l := &Loader{cache: make(map[string]interface{})}
	resolved, ok := l.Resolve("demo", base)
	if !ok {
		t.Fatal("expected to resolve bare module")
	}
	want := canonical(filepath.Join(demo, "index.abs"))
	if resolved != want {
		t.Errorf("resolved = %q, want %q", resolved, want)
	}

	// equivalent path should resolve to the same canonical key
	resolved2, ok := l.Resolve("./demo/index.abs", base)
	if !ok || resolved2 != want {
		t.Errorf("equivalent path resolved = %q, ok=%v, want %q", resolved2, ok, want)
	}
}

func TestResolveSearchesBaseDirFirst(t *testing.T) {
	base := t.TempDir()
	mp := t.TempDir()
	for _, d := range []string{base, mp} {
		demo := filepath.Join(d, "demo")
		if err := os.MkdirAll(demo, 0755); err != nil {
			t.Fatal(err)
		}
	}
	os.WriteFile(filepath.Join(base, "demo", "index.abs"), []byte("return 1"), 0644)
	os.WriteFile(filepath.Join(mp, "demo", "index.abs"), []byte("return 2"), 0644)

	l := &Loader{cache: make(map[string]interface{}), modulePath: []string{canonical(mp)}}
	resolved, ok := l.Resolve("demo", base)
	if !ok {
		t.Fatal("expected to resolve")
	}
	want := canonical(filepath.Join(base, "demo", "index.abs"))
	if resolved != want {
		t.Errorf("expected base dir to win, got %q want %q", resolved, want)
	}
}

func TestResolveMissing(t *testing.T) {
	l := &Loader{cache: make(map[string]interface{})}
	if _, ok := l.Resolve("nope", t.TempDir()); ok {
		t.Error("expected missing module to not resolve")
	}
}

func TestCacheKeysSorted(t *testing.T) {
	l := &Loader{cache: make(map[string]interface{})}
	l.CacheSet("/c", nil)
	l.CacheSet("/a", nil)
	l.CacheSet("/b", nil)
	keys := l.CacheKeys()
	if len(keys) != 3 {
		t.Fatalf("expected 3 keys, got %d", len(keys))
	}
	if keys[0] != "/a" || keys[1] != "/b" || keys[2] != "/c" {
		t.Errorf("keys not sorted: %v", keys)
	}
}

func TestCycleChain(t *testing.T) {
	l := &Loader{cache: make(map[string]interface{})}
	l.PushLoadStack("/a")
	l.PushLoadStack("/b")
	chain := l.CycleChain("/a")
	want := "/a -> /b -> /a"
	if chain != want {
		t.Errorf("chain = %q, want %q", chain, want)
	}
}

func TestInLoadStack(t *testing.T) {
	l := &Loader{cache: make(map[string]interface{})}
	if l.InLoadStack("/a") {
		t.Error("empty stack should not contain /a")
	}
	l.PushLoadStack("/a")
	if !l.InLoadStack("/a") {
		t.Error("stack should contain /a")
	}
	if l.InLoadStack("/b") {
		t.Error("stack should not contain /b")
	}
	l.PopLoadStack()
	if l.InLoadStack("/a") {
		t.Error("after pop, stack should not contain /a")
	}
}

func TestCacheInfoAndReset(t *testing.T) {
	l := &Loader{cache: make(map[string]interface{})}
	l.RecordMiss()
	l.CacheSet("/a", nil)
	l.CacheGet("/a") // hit
	hits, misses, size, inflight := l.CacheInfo()
	if hits != 1 || misses != 1 || size != 1 || inflight != 0 {
		t.Errorf("info = %d,%d,%d,%d want 1,1,1,0", hits, misses, size, inflight)
	}
	l.PushLoadStack("/a")
	if _, _, _, inflight := l.CacheInfo(); inflight != 1 {
		t.Errorf("inflight = %d, want 1", inflight)
	}
	l.Reset()
	if hits, misses, size, inflight := l.CacheInfo(); hits != 0 || misses != 0 || size != 0 || inflight != 0 {
		t.Errorf("after reset info = %d,%d,%d,%d want 0,0,0,0", hits, misses, size, inflight)
	}
	if len(l.CacheKeys()) != 0 {
		t.Error("after reset keys should be empty")
	}
}

// canonical returns the canonical form of p for comparison.
func canonical(p string) string {
	c, _ := filepath.EvalSymlinks(p)
	if c == "" {
		c = p
	}
	return c
