{"content": "package actionlint

import (
	"fmt"
	"regexp"
	"strings"
)

// RuleActionPinning is a rule to check action and reusable workflow references use pinned versions.
type RuleActionPinning struct {
	RuleBase
	level               ActionPinningLevel
	allowedOwners       map[string]struct{}
	allowedActions      map[string]struct{}
	deniedOwners        map[string]struct{}
	deniedActions       map[string]struct{}
	enabled             bool
	cliLevelOverride    bool
	cliLevel            ActionPinningLevel
}

// NewRuleActionPinning creates a new RuleActionPinning instance.
func NewRuleActionPinning() *RuleActionPinning {
	return &RuleActionPinning{
		RuleBase: RuleBase{
			name: "action-pinning",
			desc: "Checks for action and reusable workflow references to use pinned versions",
		},
	}
}

// SetConfig populates user configuration of actionlint to the rule.
func (rule *RuleActionPinning) SetConfig(cfg *Config) {
	rule.RuleBase.SetConfig(cfg)
	rule.applyConfig(cfg)
}

func (rule *RuleActionPinning) applyConfig(cfg *Config) {
	// CLI override enables the rule even when config is not set
	if rule.cliLevelOverride {
		rule.level = rule.cliLevel
		rule.enabled = true
		rule.allowedOwners = nil
		rule.allowedActions = nil
		rule.deniedOwners = nil
		rule.deniedActions = nil
		return
	}

	if cfg == nil || cfg.ActionPinning == nil {
		rule.enabled = false
		return
	}

	rule.enabled = true

	// Determine level
	switch cfg.ActionPinning.Level {
	case "major-minor":
		rule.level = ActionPinningLevelMajorMinor
	case "semver":
		rule.level = ActionPinningLevelSemver
	case "commit-sha":
		rule.level = ActionPinningLevelCommitSha
	default:
		rule.level = ActionPinningLevelSemver // default
	}

	// Merge allow/deny lists from global config
	rule.allowedOwners = make(map[string]struct{}, len(cfg.ActionPinning.AllowedOwners))
	for _, o := range cfg.ActionPinning.AllowedOwners {
		rule.allowedOwners[strings.ToLower(o)] = struct{}{}
	}

	rule.allowedActions = make(map[string]struct{}, len(cfg.ActionPinning.AllowedActions))
	for _, a := range cfg.ActionPinning.AllowedActions {
		rule.allowedActions[strings.ToLower(a)] = struct{}{}
	}

	rule.deniedOwners = make(map[string]struct{}, len(cfg.ActionPinning.DeniedOwners))
	for _, o := range cfg.ActionPinning.DeniedOwners {
		rule.deniedOwners[strings.ToLower(o)] = struct{}{}
	}

	rule.deniedActions = make(map[string]struct{}, len(cfg.ActionPinning.DeniedActions))
	for _, a := range cfg.ActionPinning.DeniedActions {
		rule.deniedActions[strings.ToLower(a)] = struct{}{}
	}
}

// ApplyConfigForPath applies the per-path override configuration. This is called when the rule
// is configured for a specific path via the paths section.
func (rule *RuleActionPinning) ApplyConfigForPath(cfg *Config, pathCfg *PathConfig) {
	if pathCfg == nil || pathCfg.ActionPinning == nil {
		// No per-path override; apply global config only
		rule.applyConfig(cfg)
		return
	}

	// Per-path entry enables the rule even without global section
	if cfg == nil || cfg.ActionPinning == nil {
		// No global config, but per-path entry enables the rule
		rule.enabled = true
		rule.level = ActionPinningLevelSemver // default

		if pathCfg.ActionPinning.Level != "" {
			switch pathCfg.ActionPinning.Level {
			case "major-minor":
				rule.level = ActionPinningLevelMajorMinor
			case "semver":
				rule.level = ActionPinningLevelSemver
			case "commit-sha":
				rule.level = ActionPinningLevelCommitSha
			}
		}

		// Merge per-path allow/deny lists
		rule.mergeLists(pathCfg.ActionPinning)
		return
	}

	// Both global and per-path configs exist: merge by union
	// First apply global config
	rule.applyConfig(cfg)

	// Then merge per-path lists into the existing ones
	rule.mergeListsForOverride(pathCfg.ActionPinning)
}

func (rule *RuleActionPinning) mergeLists(pc *ActionPinningConfig) {
	if rule.allowedOwners == nil {
		rule.allowedOwners = make(map[string]struct{})
	}
	for _, o := range pc.AllowedOwners {
		rule.allowedOwners[strings.ToLower(o)] = struct{}{}
	}

	if rule.allowedActions == nil {
		rule.allowedActions = make(map[string]struct{})
	}
	for _, a := range pc.AllowedActions {
		rule.allowedActions[strings.ToLower(a)] = struct{}{}
	}

	if rule.deniedOwners == nil {
		rule.deniedOwners = make(map[string]struct{})
	}
	for _, o := range pc.DeniedOwners {
		rule.deniedOwners[strings.ToLower(o)] = struct{}{}
	}

