// Parse {owner}/{repo}@{ref} or {owner}/{repo}/{path}@{ref}
func (rule *RuleActionPinning) checkRepoAction(spec string, exec *ExecAction) {
	idx := strings.LastIndexRune(spec, '@')
	if idx == -1 {
		return // Invalid format; the existing "action" rule will report this
