	ref := spec[idx+1:]
	action := spec[:idx]

	owner, repo := splitOwnerRepo(action)
	if owner == "" || repo == "" {
		return // Invalid format; the existing "action" rule will report this
	}

	// Check if this action is denied
	if rule.isDenied(owner, repo) {
		rule.checkPinning(spec, ref, exec.Uses.Pos, false)
		return
	}

	// Check if this action is in the allowed list
	if rule.isAllowed(owner, repo) {
		rule.checkPinning(spec, ref, exec.Uses.Pos, true)
		return
	}

	// Check if this is a known popular action
	if meta, ok := PopularActions[spec]; ok {
		rule.checkPinningWithKnownVersion(spec, ref, meta, exec.Uses.Pos)
		return
	}

	// For other actions, check pinning without known version suggestion
	rule.checkPinning(spec, ref, exec.Uses.Pos, false)
}

// Parse {owner}/{repo}/{path}@{ref} for reusable workflow calls
func (rule *RuleActionPinning) checkRepoWorkflowCall(spec string, job *Job) {
	u := job.WorkflowCall.Uses.Value
	idx := strings.LastIndexRune(u, '@')
	if idx == -1 {
		return // Invalid format; the existing "workflow-call" rule will report this
	}
	ref := u[idx+1:]
	workflow := u[:idx]

	owner, repo := splitOwnerRepo(workflow)
	if owner == "" || repo == "" {
		return // Invalid format
	}

	if rule.isDenied(owner, repo) {
		rule.checkPinning(u, ref, job.WorkflowCall.Uses.Pos, true)
		return
	}

	if rule.isAllowed(owner, repo) {
		rule.checkPinning(u, ref, job.WorkflowCall.Uses.Pos, false)
		return
	}

	// Check pinning without known version suggestion
	rule.checkPinning(u, ref, job.WorkflowCall.Uses.Pos, false)
}

// splitOwnerRepo extracts owner and repo from "owner/repo" or "owner/repo/path" format.
func splitOwnerRepo(s string) (string, string) {
	idx := strings.IndexRune(s, '/')
	if idx <= 0 {
		return "", ""
	}
	owner := s[:idx]
	rest := s[idx+1:]
	// Extract repo (up to next '/' or end)
	if idx2 := strings.IndexRune(rest, '/'); idx2 >= 0 {
		repo := rest[:idx2]
		if repo == "" {
			return "", ""
		}
		return owner, repo
	}
	return owner, rest
}

var reCommitSHA = regexp.MustCompile(`^[0-9a-f]{40}$`)
var reSemver = regexp.MustCompile(`^v[0-9]+\.[0-9]+\.[0-9]+([0-9A-Za-z.\-+]*)?$`)
var reMajorMinor = regexp.MustCompile(`^v[0-9]+\.[0-9]+$`)

// isPinned checks if the given ref satisfies the given pinning level or any stricter level.
func (rule *RuleActionPinning) isPinned(ref string, level ActionPinningLevel) bool {
	if level == ActionPinningLevelUnset {
		level = ActionPinningLevelSemver
	}

	// Check from the strictest level down to the requested level
	if level <= ActionPinningLevelCommitSha && reCommitSHA.MatchString(ref) {
		return true
	}
	if level <= ActionPinningLevelSemver && reSemver.MatchString(ref) {
		return true
	}
	if level <= ActionPinningLevelMajorMinor && reMajorMinor.MatchString(ref) {
		return true
	}

	return false
}

// checkPinning checks if the ref is pinned according to the configured level.
func (rule *RuleActionPinning) checkPinning(spec, ref string, pos *Pos, isDenied bool) {
	if rule.isPinned(ref, rule.level) {
		return
	}

	where := "action"
	if isDenied {
		where = "denied " + where
	}

	msg := fmt.Sprintf("%s %q is not pinned to a specific version. pinned with %s", where, spec, rule.level.String())
	rule.Errorf(pos, msg)
}

// checkPinningWithKnownVersion checks pinning and suggests the known version for popular actions.
func (rule *RuleActionPinning) checkPinningWithKnownVersion(spec, ref string, meta *ActionMetadata, pos *Pos) {
	if rule.isPinned(ref, rule.level) {
		return
	}

	// Get the spec's version to suggest a known version
	knownSpec := spec
	knownVersion := ""

	// Extract version from the spec's @ref
	if idx := strings.LastIndex(spec, "@"); idx >= 0 {
		knownVersion = spec[idx+1:]
	}

	// Try to find a more specific known version
	if knownVersion == "" {
		knownVersion = meta.Name
	}

	rule.Errorf(pos, "action %q is not pinned to a specific version. pinned with %s. known version: %s", spec, rule.level.String(), knownSpec)
}

// isAllowed checks if the action is in the allowed list.
func (rule *RuleActionPinning) isAllowed(owner, repo string) bool {
	if len(rule.allowedActions) > 0 {
