func TestRuleActionPinningConfigValidation(t *testing.T) {
	tests := []struct {
		what   string
		config string
		want   string
	}{
		{
			what:   "invalid level",
			config: "action-pinning:\n  level: invalid",
			want:   "invalid action-pinning level",
		},
		{
			what:   "owner with slash in allowed-owners",
			config: "action-pinning:\n  allowed-owners: [actions/checkout]",
			want:   "must not contain '/'",
		},
		{
			what:   "owner with slash in denied-owners",
			config: "action-pinning:\n  denied-owners: [actions/checkout]",
			want:   "must not contain '/'",
		},
		{
			what:   "malformed owner/repo in allowed-actions",
			config: "action-pinning:\n  allowed-actions: [actions]",
			want:   "expected \"owner/repo\" format",
		},
		{
			what:   "malformed owner/repo in denied-actions",
			config: "action-pinning:\n  denied-actions: [actions]",
			want:   "expected \"owner/repo\" format",
		},
		{
			what:   "empty config enables rule with default level",
			config: "action-pinning: {}",
			want:   "",
		},
		{
			what:   "null config disables rule",
			config: "action-pinning: null",
			want:   "",
		},
	}

	for _, tc := range tests {
		t.Run(tc.what, func(t *testing.T) {
			c, err := ParseConfig([]byte(tc.config))
			if err != nil {
				if tc.want == "" {
					t.Fatalf("unexpected error: %v", err)
				}
				if !contains(err.Error(), tc.want) {
					t.Fatalf("error %q should contain %q", err.Error(), tc.want)
				}
				return
			}

			if tc.want != "" {
				t.Fatal("expected error but got none")
			}

			rule := NewRuleActionPinning()
			rule.SetConfig(c)

			if tc.config == "action-pinning: null" {
				if rule.enabled {
					t.Fatal("rule should be disabled when action-pinning is null")
				}
				return
			}

			if !rule.enabled {
				t.Fatal("rule should be enabled when action-pinning is {}")
			}

			if rule.level != ActionPinningLevelSemver {
				t.Fatalf("default level should be semver but got %v", rule.level)
			}
		})
	}
}

func contains(s, substr string) bool {
	return len(s) >= len(substr) && (s == substr || len(substr) == 0 || indexOf(s, substr) >= 0)
}

func indexOf(s, substr string) int {
	for i := 0; i+len(substr) <= len(s); i++ {
		if s[i:i+len(substr)] == substr {
			return i
		}
	}
	return -1
}

