def _format_snapshot_summary(snap: SnapshotSummary) -> Tuple[str, str, str, str]:
    name = snap.name if snap.name is not None else "-"
    return (
        str(snap.id),
        name,
        str(snap.running_count),
        str(snap.terminated_count),
    )


@snapshot_cli.command(name="save")
@click.option("--name", "name", default=None, help="Optional name for the snapshot")
@custom_help_option
@auto_command_done
def do_snapshot_save(ctx: click.Context, name: str) -> None:
    """Save the current task state as a snapshot"""
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()

    @auto_async_command_done
    async def _do_save(ctx: click.Context) -> None:
        snapshot_id = await self.capture_snapshot(name)
        stdout.write(f"Snapshot {snapshot_id} saved")
        if name is not None:
            stdout.write(f" with name '{name}'")
        stdout.write("\n")
        stdout.flush()

    task = self._ui_loop.create_task(_do_save(ctx))
    self._termui_tasks.add(task)


@snapshot_cli.command(name="list", aliases=["ls"])
@custom_help_option
@auto_command_done
def do_snapshot_list(ctx: click.Context) -> None:
    """List all snapshots"""
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()
    headers = ("ID", "Name", "Running", "Terminated")
    table_data: List[Tuple[str, str, str, str]] = [headers]
    for snap in self.list_snapshots():
        table_data.append(_format_snapshot_summary(snap))
    if len(table_data) == 1:
        stdout.write("No snapshots\n")
        return
    table = AsciiTable(table_data)
    table.inner_row_border = False
    table.inner_column_border = False
    stdout.write(f"{len(table_data) - 1} snapshots\n")
    stdout.write(table.table)
    stdout.write("\n")
    stdout.flush()


@snapshot_cli.command(name="show")
@click.argument("snapshot_id", shell_complete=complete_snapshot_id)
