@auto_command_done
def do_snapshot_show(ctx: click.Context, snapshot_id: str) -> None:
    """Show details of a snapshot"""
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()
    try:
        sid = int(snapshot_id)
    except ValueError:
        print_fail(f"Invalid snapshot ID: {snapshot_id}")
        return
    try:
        snap = self.get_snapshot(sid)
    except KeyError:
        print_fail(f"No snapshot {sid}")
        return
    name = snap.name if snap.name is not None else "-"
    stdout.write(f"Snapshot {sid} (name: {name})\n")
    stdout.write(f"Running tasks: {len(snap.running_tasks)}\n")
    stdout.write(f"Terminated tasks: {len(snap.terminated_tasks)}\n")
    stdout.flush()


