                task.since,
            ))
        table = AsciiTable(table_data)
        table.inner_row_border = False
        table.inner_column_border = False
        stdout.write(table.table)
        stdout.write("\n")
    if diff.common:
        stdout.write("Common:\n")
        table_data = [headers]
        for task in diff.common:
            table_data.append((
                task.task_id,
                task.state,
                task.name,
